290→// Three scenarios:
291→//  1. Local branch doesn't exist, remote does → create local from remote
292→//  2. Local branch exists but is empty, remote has data → update local from remote
293→//  3. No local or remote branch → create empty orphan
294→func EnsureMetadataBranch(repo *git.Repository) error {
