package strategy

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"sync"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/paths"

	"github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/object"
)

func TestOpenRepository(t *testing.T) {
	// Create a temporary directory for the test repository
	tmpDir := t.TempDir()

	// Initialize a git repository
	repo, err := git.PlainInit(tmpDir, false)
	if err != nil {
		t.Fatalf("failed to init repo: %v", err)
	}

	// Create a test file and commit it
	testFile := filepath.Join(tmpDir, "test.txt")
	if err := os.WriteFile(testFile, []byte("test content"), 0o644); err != nil {
		t.Fatalf("failed to write test file: %v", err)
	}

	worktree, err := repo.Worktree()
	if err != nil {
		t.Fatalf("failed to get worktree: %v", err)
	}

	if _, err := worktree.Add("test.txt"); err != nil {
		t.Fatalf("failed to add file: %v", err)
	}

	if _, err := worktree.Commit("Initial commit", &git.CommitOptions{
		Author: &object.Signature{
			Name:  "Test User",
			Email: "test@example.com",
		},
	}); err != nil {
		t.Fatalf("failed to commit: %v", err)
	}

	// Change to the repository directory
	t.Chdir(tmpDir)

	// Test OpenRepository
	openedRepo, err := OpenRepository()
	if err != nil {
		t.Fatalf("OpenRepository() failed: %v", err)
	}

	if openedRepo == nil {
		t.Fatal("OpenRepository() returned nil repository")
	}

	// Verify we can perform basic operations
	head, err := openedRepo.Head()
	if err != nil {
		t.Fatalf("failed to get HEAD: %v", err)
	}

	if head == nil {
		t.Fatal("HEAD is nil")
	}

	// Verify we can get the commit
	commit, err := openedRepo.CommitObject(head.Hash())
	if err != nil {
		t.Fatalf("failed to get commit: %v", err)
	}

	if commit.Message != "Initial commit" {
		t.Errorf("expected commit message 'Initial commit', got '%s'", commit.Message)
	}
}

func TestOpenRepositoryError(t *testing.T) {
	// Create a temporary directory without git repository
	tmpDir := t.TempDir()

	// Change to the non-repository directory
	t.Chdir(tmpDir)

	// Test OpenRepository should fail
	_, err := OpenRepository()
	if err == nil {
		t.Fatal("OpenRepository() should have failed in non-repository directory")
	}
}

func TestWorktreeRoot_Cache(t *testing.T) {
	// Uses t.Chdir + t.Setenv so cannot be parallel.
	tmpDir := t.TempDir()
	initTestRepo(t, tmpDir)
	t.Chdir(tmpDir)
	paths.ClearWorktreeRootCache()

	// First call populates the cache via git.
	got, err := paths.WorktreeRoot()
	if err != nil {
		t.Fatalf("paths.WorktreeRoot() first call error: %v", err)
	}

	// Resolve symlinks for comparison (macOS /var -> /private/var).
	want, err := filepath.EvalSymlinks(tmpDir)
	if err != nil {
		t.Fatalf("EvalSymlinks error: %v", err)
	}
	if got != want {
		t.Fatalf("paths.WorktreeRoot() = %q, want %q", got, want)
	}

	// Break git by pointing PATH at an empty directory.
	// If the second call hits git it will fail.
	emptyDir := t.TempDir()
	t.Setenv("PATH", emptyDir)

	got2, err := paths.WorktreeRoot()
	if err != nil {
		t.Fatalf("paths.WorktreeRoot() cached call should succeed, got error: %v", err)
	}
	if got2 != want {
		t.Fatalf("paths.WorktreeRoot() cached = %q, want %q", got2, want)
	}

	// After clearing the cache the broken PATH should cause a failure.
	paths.ClearWorktreeRootCache()
