1351→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
1352→	obj := repo.Storer.NewEncodedObject()
1353→	obj.SetType(plumbing.BlobObject)
1354→	obj.SetSize(int64(len(content)))
1355→
1356→	writer, err := obj.Writer()
