147→// spliceCheckpointSubtree builds a tree from checkpoint-local entries and installs it
148→// at the correct shard location in the root tree using O(depth) tree surgery.
149→// basePath is like "a3/b2c4d5e6f7/" (with trailing slash).
150→// Returns the new root tree hash.
151→func (s *GitStore) spliceCheckpointSubtree(rootTreeHash plumbing.Hash, checkpointID id.CheckpointID, basePath string, entries map[string]object.TreeEntry) (plumbing.Hash, error) {
152→	// Convert entries to relative paths (strip basePath prefix)
153→	relEntries := make(map[string]object.TreeEntry, len(entries))
154→	for path, entry := range entries {
155→		relPath := strings.TrimPrefix(path, basePath)
156→		if relPath == path {
157→			continue // Entry doesn't have the expected prefix
158→		}
159→		relEntries[relPath] = entry
160→	}
161→
162→	// Build the checkpoint subtree from relative entries
163→	checkpointTreeHash, err := BuildTreeFromEntries(s.repo, relEntries)
164→	if err != nil {
165→		return plumbing.ZeroHash, fmt.Errorf("failed to build checkpoint subtree: %w", err)
166→	}
167→
168→	// Splice into root tree at the shard path using tree surgery
169→	// Path: ["a3"] with entry "b2c4d5e6f7" pointing to the checkpoint tree
170→	shardPrefix := string(checkpointID[:2])
171→	shardSuffix := string(checkpointID[2:])
172→	return UpdateSubtree(s.repo, rootTreeHash, []string{shardPrefix}, []object.TreeEntry{
173→		{Name: shardSuffix, Mode: filemode.Dir, Hash: checkpointTreeHash},
174→	}, UpdateSubtreeOptions{MergeMode: MergeKeepExisting})
175→}
